function iopRun(string$cli,array$env,array$args=['--email','owner@shlz.ru']):array{
    $pipes=[];$base=getenv();if(!is_array($base))throw new TestFailure('SETUP_FAILURE env');
    $p=proc_open([PHP_BINARY,$cli,...$args],[0=>['file','/dev/null','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes,dirname($cli,2),array_replace($base,$env));
    if(!is_resource($p))throw new TestFailure('SETUP_FAILURE CLI');$out=stream_get_contents($pipes[1]);$err=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);return[proc_close($p),$out,$err];
}
function iopStart(string$cli,array$env):array{$pipes=[];$base=getenv();$p=proc_open([PHP_BINARY,$cli,'--email','owner@shlz.ru'],[0=>['file','/dev/null','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes,dirname($cli,2),array_replace(is_array($base)?$base:[],$env));if(!is_resource($p))throw new TestFailure('SETUP_FAILURE concurrent CLI');return[$p,$pipes];}
function iopFinish(array$child):array{[$p,$pipes]=$child;stream_set_blocking($pipes[1],false);stream_set_blocking($pipes[2],false);$out='';$err='';$deadline=microtime(true)+10;do{$out.=stream_get_contents($pipes[1]);$err.=stream_get_contents($pipes[2]);$status=proc_get_status($p);if(!$status['running'])break;if(microtime(true)>=$deadline){proc_terminate($p,9);throw new TestFailure('SETUP_FAILURE concurrent CLI timeout');}usleep(10000);}while(true);$out.=stream_get_contents($pipes[1]);$err.=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);$closed=proc_close($p);return[$status['exitcode']>=0?$status['exitcode']:$closed,$out,$err];}
function iopSnapshot(mysqli$db,string$p):array{$out=[];foreach(['fm2_pilot_users','fm2_pilot_roles','fm2_pilot_role_permissions','fm2_pilot_user_roles','fm2_pilot_auth_credentials','fm2_pilot_invitations','fm2_pilot_user_role_events','fm2_pilot_auth_attempts','fm2_pilot_user_status_events']as$t)$out[$t]=$db->query("SELECT * FROM `{$p}{$t}` ORDER BY 1,2")->fetch_all(MYSQLI_ASSOC);return$out;}
function iopCatalogHash(mysqli$db,string$p):string{$roles=[];foreach($db->query("SELECT role_id,code,name,description FROM `{$p}fm2_pilot_roles`")->fetch_all(MYSQLI_ASSOC)as$r){$permissions=array_column($db->query("SELECT permission FROM `{$p}fm2_pilot_role_permissions` WHERE role_id=".(int)$r['role_id'])->fetch_all(MYSQLI_ASSOC),'permission');sort($permissions,SORT_STRING);$roles[]=['code'=>$r['code'],'name'=>$r['name'],'description'=>$r['description'],'permissions'=>$permissions];}usort($roles,static fn(array$a,array$b):int=>$a['code']<=>$b['code']);return hash('sha256',json_encode($roles,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR));}
function iopFixture(mysqli$admin,string$host,int$port,string$adminUser,string$adminPassword,array&$databases,array&$dbUsers):array{
    $token=bin2hex(random_bytes(5));$name='t_initial_owner_'.$token;$user='iop_'.$token;$runtimePassword='Dml-'.$token.'-Secret!';$prefix='owner_';$databases[]=$name;$dbUsers[]=$user;
    $admin->query("CREATE DATABASE `{$name}` DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");$db=new mysqli($host,$adminUser,$adminPassword,$name,$port);$m=CanonicalMigrationApplication::run($db,$prefix,ProductionPilotMigrationCatalogue::migrations());assertSameValue([0,true,22],[$m['exitCode'],$m['result']['ok']??null,$m['result']['schemaVersion']??null],'canonical v22 prerequisite');
    $escaped=$admin->real_escape_string($runtimePassword);$admin->query("CREATE USER `{$user}`@'%' IDENTIFIED BY '{$escaped}'");$admin->query("GRANT SELECT,INSERT,UPDATE,DELETE ON `{$name}`.* TO `{$user}`@'%'");
    $env=['FMONITOR_DB_HOST'=>$host,'FMONITOR_DB_PORT'=>(string)$port,'FMONITOR_DB_NAME'=>$name,'FMONITOR_DB_USER'=>$user,'FMONITOR_DB_PASSWORD'=>$runtimePassword,'FMONITOR_PROCESS_TABLE_PREFIX'=>$prefix,'FMONITOR_BOOTSTRAP_SUPERADMIN_PASSWORD'=>'Synthetic Owner Password 2026!'];return[$db,$env,$prefix];
}
try{
    [$db,$env,$p]=iopFixture($admin,$host,$port,$adminUser,$adminPassword,$databases,$dbUsers);
