    assertSameValue(1,(int)$db->query("SELECT COUNT(*)n FROM `{$p}fm2_pilot_users`")->fetch_assoc()['n'],'exactly one owner user');assertSameValue(['owner@shlz.ru','owner@shlz.ru',1,'active'],[$user['full_name'],$user['email'],(int)$user['status'],$user['activation_state']],'one active normalized owner');assertSameValue(true,str_starts_with((string)$credential['password_hash'],'$argon2id$'),'credential uses Argon2id');assertSameValue(true,password_verify($env['FMONITOR_BOOTSTRAP_SUPERADMIN_PASSWORD'],$credential['password_hash']),'Argon credential verifies');assertSameValue([['code'=>'superadministrator','origin'=>'bootstrap','assigned_by_user_id'=>null],['code'=>'user','origin'=>'bootstrap','assigned_by_user_id'=>null]],$grants,'exact existing bootstrap grants');assertSameValue('f20f4831eecb2e5e8cc4df0b0479c9492617c1cc70c758a426796b5966ce7391',iopCatalogHash($db,$p),'exact independently frozen LocalRoleCatalog definitions and permissions');
    $ownerBefore=iopSnapshot($db,$p);assertSameValue([0,"{\"ok\":true,\"status\":\"already_provisioned\"}\n",''],iopRun($cli,$env),'exact replay');assertSameValue($ownerBefore,iopSnapshot($db,$p),'exact replay byte/value zero mutation');
    $different=$env;$different['FMONITOR_BOOTSTRAP_SUPERADMIN_PASSWORD']='Different Synthetic Secret!';assertSameValue([65,"{\"ok\":false,\"reason\":\"IDENTITY_NOT_EMPTY\"}\n",''],iopRun($cli,$different),'different password refuses');assertSameValue($ownerBefore,iopSnapshot($db,$p),'conflict zero mutation');
    [$conflict,$conflictEnv,$cp]=iopFixture($admin,$host,$port,$adminUser,$adminPassword,$databases,$dbUsers);$conflict->query("INSERT INTO `{$cp}fm2_pilot_users`(full_name,email,phone,status,activation_state,session_version,source_updated_at)VALUES('Existing','existing@shlz.ru','',1,'invited',1,'2026-09-09T00:00:00+03:00')");$conflictBefore=iopSnapshot($conflict,$cp);assertSameValue([65,"{\"ok\":false,\"reason\":\"IDENTITY_NOT_EMPTY\"}\n",''],iopRun($cli,$conflictEnv),'existing invited user refuses');assertSameValue($conflictBefore,iopSnapshot($conflict,$cp),'existing state zero mutation');$conflict->close();
    [$partial,$partialEnv,$pp]=iopFixture($admin,$host,$port,$adminUser,$adminPassword,$databases,$dbUsers);$partial->query("INSERT INTO `{$pp}fm2_pilot_roles`(code,name,description,status,source_updated_at)VALUES('partial','Partial','Preexisting partial state',1,'2026-09-09T00:00:00+03:00')");$partialBefore=iopSnapshot($partial,$pp);assertSameValue([65,"{\"ok\":false,\"reason\":\"IDENTITY_NOT_EMPTY\"}\n",''],iopRun($cli,$partialEnv),'partial identity table with zero users refuses');assertSameValue($partialBefore,iopSnapshot($partial,$pp),'partial role state zero mutation');$partial->close();
    foreach([[],['--email'],['--email','bad@example.test']]as$args){assertSameValue([64,"{\"ok\":false,\"reason\":\"CONFIGURATION_INVALID\"}\n",''],iopRun($cli,$env,$args),'invalid args stable and secret-free');}$invalid=$env;unset($invalid['FMONITOR_DB_PASSWORD']);assertSameValue([64,"{\"ok\":false,\"reason\":\"CONFIGURATION_INVALID\"}\n",''],iopRun($cli,$invalid),'missing config stable and secret-free');assertSameValue($ownerBefore,iopSnapshot($db,$p),'all invalid args/config outcomes preserve full identity state');$db->close();
    [$missing,$missingEnv,$mp]=iopFixture($admin,$host,$port,$adminUser,$adminPassword,$databases,$dbUsers);$missing->query("DROP TABLE `{$mp}fm2_pilot_auth_credentials`");$tablesBefore=$missing->query("SELECT TABLE_NAME FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() ORDER BY TABLE_NAME")->fetch_all(MYSQLI_ASSOC);assertSameValue([70,"{\"ok\":false,\"reason\":\"SCHEMA_NOT_READY\"}\n",''],iopRun($cli,$missingEnv),'missing schema fails without DDL');assertSameValue($tablesBefore,$missing->query("SELECT TABLE_NAME FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() ORDER BY TABLE_NAME")->fetch_all(MYSQLI_ASSOC),'missing schema no repair');$missing->close();
    [$busy,$busyEnv,$bp]=iopFixture($admin,$host,$port,$adminUser,$adminPassword,$databases,$dbUsers);$lock=hash('sha256',$busyEnv['FMONITOR_DB_NAME']."\0".$bp."\0initial-owner");$hold=$busy->prepare('SELECT GET_LOCK(?,0)');$hold->bind_param('s',$lock);$hold->execute();assertSameValue('1',(string)$hold->get_result()->fetch_column(),'busy fixture owns lock');$busyBefore=iopSnapshot($busy,$bp);assertSameValue([75,"{\"ok\":false,\"reason\":\"PROVISIONING_BUSY\"}\n",''],iopRun($cli,$busyEnv),'held lock returns bounded busy');assertSameValue($busyBefore,iopSnapshot($busy,$bp),'busy outcome zero mutation');$release=$busy->prepare('SELECT RELEASE_LOCK(?)');$release->bind_param('s',$lock);$release->execute();$busy->close();
    [$rollback,$rollbackEnv,$rp]=iopFixture($admin,$host,$port,$adminUser,$adminPassword,$databases,$dbUsers);$rollback->query("CREATE TRIGGER `{$rp}fail_initial_grant` BEFORE INSERT ON `{$rp}fm2_pilot_user_roles` FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='controlled failure'");$rollbackBefore=iopSnapshot($rollback,$rp);assertSameValue([70,"{\"ok\":false,\"reason\":\"PROVISIONING_UNAVAILABLE\"}\n",''],iopRun($cli,$rollbackEnv),'late grant failure is redacted');assertSameValue($rollbackBefore,iopSnapshot($rollback,$rp),'late failure rolls back roles user credential and grants');$rollback->query("DROP TRIGGER `{$rp}fail_initial_grant`");assertSameValue([0,"{\"ok\":true,\"status\":\"created\"}\n",''],iopRun($cli,$rollbackEnv),'retry after rollback and lock release succeeds');$rollback->close();
    [$race,$raceEnv,$racePrefix]=iopFixture($admin,$host,$port,$adminUser,$adminPassword,$databases,$dbUsers);$children=[iopStart($cli,$raceEnv),iopStart($cli,$raceEnv)];$results=array_map('iopFinish',$children);$statuses=array_column($results,1);sort($statuses,SORT_STRING);$allowed=[["{\"ok\":false,\"reason\":\"PROVISIONING_BUSY\"}\n","{\"ok\":true,\"status\":\"created\"}\n"],["{\"ok\":true,\"status\":\"already_provisioned\"}\n","{\"ok\":true,\"status\":\"created\"}\n"]];assertSameValue(true,in_array($statuses,$allowed,true),'concurrent calls produce one create and busy or replay');assertSameValue(1,(int)$race->query("SELECT COUNT(*)n FROM `{$racePrefix}fm2_pilot_users`")->fetch_assoc()['n'],'concurrent calls create exactly one owner');$race->close();
    echo"PASS: INITIAL-OWNER-PROVISIONING-001 explicit clean owner CLI\n";
}finally{foreach($dbUsers as$u)try{$admin->query("DROP USER IF EXISTS `{$u}`@'%'");}catch(Throwable){}foreach($databases as$d)try{$admin->query("DROP DATABASE IF EXISTS `{$d}`");}catch(Throwable){}$admin->close();}
